import React, { useState, useEffect } from 'react';
import './Registro.css';

function Registro() {
  const [formData, setFormData] = useState({
    nombre: '',
    apellido: '',
    dni: '',
    email: '',
    nro_celular: '',
    id_direccion: '',
    id_localidad: '', // ID de la localidad seleccionada
    id_rol: 2,
    password: '',
  });

  const [localidades, setLocalidades] = useState([]);
  const [loadingLocalidades, setLoadingLocalidades] = useState(false);

  // Cargar localidades de la provincia de Corrientes
  const fetchLocalidades = async () => {
    try {
      setLoadingLocalidades(true);
      const response = await fetch('http://localhost:4000/api/localidades/corrientes'); // Asegúrate de que este endpoint esté disponible en tu backend
      const data = await response.json();
      setLocalidades(data);
    } catch (error) {
      console.error('Error al obtener las localidades:', error);
    } finally {
      setLoadingLocalidades(false);
    }
  };

  useEffect(() => {
    fetchLocalidades();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevData => ({
      ...prevData,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch('http://localhost:4000/api/registro', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(formData)
      });

      if (response.ok) {
        alert('¡Usuario registrado exitosamente!');
      } else {
        alert('Hubo un error al registrar el usuario.');
      }
    } catch (error) {
      console.error('Error en el registro:', error);
    }
  };

  return (
    <div className="registro-container">
      <div className="registro-form">
        <h2>Crear Cuenta</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            name="nombre"
            placeholder="Nombre"
            value={formData.nombre}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="apellido"
            placeholder="Apellido"
            value={formData.apellido}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="dni"
            placeholder="DNI"
            value={formData.dni}
            onChange={handleChange}
            required
          />
          <input
            type="email"
            name="email"
            placeholder="Correo electrónico"
            value={formData.email}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="nro_celular"
            placeholder="Número de celular"
            value={formData.nro_celular}
            onChange={handleChange}
            required
          />

          {/* Campo de Localidad */}
          <select
            name="id_localidad"
            value={formData.id_localidad}
            onChange={handleChange}
            required
          >
            <option value="">Seleccione una localidad</option>
            {loadingLocalidades ? (
              <option>Cargando...</option>
            ) : (
              localidades.map((localidad) => (
                <option key={localidad.id_localidad} value={localidad.id_localidad}>
                  {localidad.nombre}
                </option>
              ))
            )}
          </select>

          <input
            type="password"
            name="password"
            placeholder="Contraseña"
            value={formData.password}
            onChange={handleChange}
            required
          />
          <button type="submit">Registrarse</button>
        </form>
      </div>
    </div>
  );
}

export default Registro;
